import{_ as e,o as i,c as t,ah as o}from"./chunks/framework.BsNNkeaH.js";const u=JSON.parse('{"title":"Discipline and councils","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/vie-scolaire/discipline-et-conseils.md","filePath":"src/en/guide/vie-scolaire/discipline-et-conseils.md"}'),s={name:"en/guide/vie-scolaire/discipline-et-conseils.md"};function r(c,n,a,l,d,g){return i(),t("div",null,[...n[0]||(n[0]=[o('<h1 id="discipline-and-councils" tabindex="-1">Discipline and councils <a class="header-anchor" href="#discipline-and-councils" aria-label="Permalink to &quot;Discipline and councils&quot;">​</a></h1><p>This page covers recording disciplinary incidents and, when an incident warrants it, convening and then deciding a disciplinary council.</p><h2 id="record-a-disciplinary-incident" tabindex="-1">Record a disciplinary incident <a class="header-anchor" href="#record-a-disciplinary-incident" aria-label="Permalink to &quot;Record a disciplinary incident&quot;">​</a></h2><ol><li>Open <strong>School life → Discipline incidents</strong>, then click <strong>New incident</strong>.</li><li>Choose the <strong>Student</strong> involved and, if relevant, their <strong>Class</strong> (leave it blank if there&#39;s no specific class to note).</li><li>Enter the <strong>Date</strong> of the incident and its <strong>Severity</strong>: <strong>Minor</strong>, <strong>Major</strong> or <strong>Severe</strong>.</li><li>Describe the incident in <strong>Description</strong> (required) and, if a sanction was already applied at the time, note it in <strong>Sanction</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>The list of incidents can be filtered by student name, class and severity. From this list, <strong>Edit</strong> reopens the incident and <strong>Delete</strong> permanently removes it after confirmation — this cannot be undone.</p><h2 id="convene-and-manage-a-disciplinary-council" tabindex="-1">Convene and manage a disciplinary council <a class="header-anchor" href="#convene-and-manage-a-disciplinary-council" aria-label="Permalink to &quot;Convene and manage a disciplinary council&quot;">​</a></h2><p>A disciplinary council can be convened from an existing incident or started on its own.</p><ol><li>From the <strong>Discipline incidents</strong> list, click <strong>Convene council</strong> on the row for the relevant incident (or open <strong>School life → Disciplinary councils</strong> directly, then <strong>New council</strong>, to start from a blank form).</li><li>Choose the <strong>Student</strong>, their <strong>Class</strong> if relevant, and the <strong>Related incident</strong> if the council follows a specific incident — the reason then pre-fills with the incident&#39;s description, which you can edit.</li><li>Fill in the council&#39;s <strong>Reason</strong> and its <strong>Session date</strong>.</li><li>Build the <strong>Council members</strong> list: for each one, choose the person from staff and their role (<strong>President</strong>, <strong>Secretary</strong> or <strong>Member</strong>); use <strong>Add member</strong> to include several.</li><li>Click <strong>Save</strong> — the council is created with the status <strong>Scheduled</strong>.</li></ol><p>On a scheduled council&#39;s page, you can still:</p><ul><li><strong>Edit</strong> its details before the session;</li><li><strong>Cancel council</strong> (with confirmation, this cannot be undone);</li><li><strong>Delete</strong> the council (with confirmation, this cannot be undone);</li><li><strong>Record decision</strong>: choose the <strong>Decision</strong> — Warning, Reprimand, Temporary exclusion, Permanent exclusion or No sanction — and add <strong>Decision details</strong> if needed, then confirm.</li></ul><p>Once the decision is recorded, the council moves to the status <strong>Decided</strong>: the decision and its date are shown, and a <strong>Download minutes</strong> button generates the corresponding document. A decided or cancelled council can no longer be edited.</p><p>The list of councils can be filtered by student name, class and status (Scheduled, Decided, Cancelled); the front desk can view and download minutes but cannot create or decide a council.</p>',12)])])}const p=e(s,[["render",r]]);export{u as __pageData,p as default};
